do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":3931,"word":"taxonomy","meaning":"分類學","example":"The taxonomy lesson grouped animals by their shared characteristics.","example_zh":"分類學課程依共同特徵將動物分組。","original_meaning":"分類學","original_example":"This zone is restricted to authorized personnel.","original_example_zh":"此區域僅限授權人員進入。"},{"source_id":3932,"word":"technocrat","meaning":"技術官僚","example":"The technocrat advised the council on improving the city's water system.","example_zh":"技術官僚就改善城市供水系統向議會提出建議。","original_meaning":"技術官僚","original_example":"The agreement was signed by both parties.","original_example_zh":"協議已由雙方簽署。"},{"source_id":3933,"word":"telecommunications","meaning":"電信","example":"The exhibition traced the development of telecommunications from cables to satellites.","example_zh":"展覽回顧電信從電纜到衛星的發展。","original_meaning":"電信","original_example":"The analysis revealed key insights.","original_example_zh":"分析揭示了關鍵洞見。"},{"source_id":3934,"word":"temperament","meaning":"性情","example":"The horse's gentle temperament made it easy to handle.","example_zh":"那匹馬溫和的性情讓人容易照料。","original_meaning":"性情","original_example":"Her application was approved quickly.","original_example_zh":"她的申請迅速獲得批准。"},{"source_id":3935,"word":"tenant","meaning":"房客","example":"The tenant asked the landlord to repair the leaking window.","example_zh":"房客請房東修理漏水的窗戶。","original_meaning":"房客","original_example":"The account balance was updated instantly.","original_example_zh":"帳戶餘額即時更新。"},{"source_id":3936,"word":"territorial","meaning":"領土的","example":"The map showed the territorial boundaries of the ancient kingdom.","example_zh":"地圖顯示古代王國的領土邊界。","original_meaning":"領土的","original_example":"The bank processed the loan request.","original_example_zh":"銀行處理了貸款申請。"},{"source_id":3937,"word":"testament","meaning":"證明；明證","example":"The flourishing garden was a testament to the volunteers' hard work.","example_zh":"茂盛花園是志工辛勤付出的明證。","original_meaning":"證明","original_example":"This benefit attracts many applicants.","original_example_zh":"這項福利吸引了許多申請者。"},{"source_id":3938,"word":"testimony","meaning":"證詞","example":"The witness gave testimony about what she had seen.","example_zh":"證人就她所見的情況作證。","original_meaning":"證詞","original_example":"The project had a limited budget.","original_example_zh":"該專案預算有限。"},{"source_id":3939,"word":"theology","meaning":"神學","example":"The library held a collection of books on theology.","example_zh":"圖書館收藏一系列神學書籍。","original_meaning":"神學","original_example":"The case was closed after investigation.","original_example_zh":"經調查後，此案已結案。"},{"source_id":3940,"word":"therapeutic","meaning":"治療的","example":"The clinic offered a therapeutic program supervised by trained professionals.","example_zh":"診所提供由受訓專業人員監督的治療課程。","original_meaning":"治療的","original_example":"This change improved system stability.","original_example_zh":"這項變更提升了系統的穩定性。"},{"source_id":3941,"word":"thesis","meaning":"論文","example":"She presented her thesis on the history of the town's bridges.","example_zh":"她發表研究城鎮橋梁歷史的論文。","original_meaning":"論文","original_example":"The chart clearly shows the upward trend.","original_example_zh":"圖表清楚顯示出上升趨勢。"},{"source_id":3942,"word":"thoroughfare","meaning":"幹道","example":"The main thoroughfare connected the station with the town center.","example_zh":"主要幹道連接車站與市中心。","original_meaning":"幹道","original_example":"The client approved the final design.","original_example_zh":"客戶批准了最終設計。"},{"source_id":3943,"word":"totalitarian","meaning":"極權的","example":"The history exhibit examined life under a totalitarian regime.","example_zh":"歷史展覽探討極權政體下的生活。","original_meaning":"極權的","original_example":"The company expanded into new markets.","original_example_zh":"該公司拓展至新市場。"},{"source_id":3944,"word":"toxin","meaning":"毒素","example":"The biologist studied a toxin produced by a type of algae.","example_zh":"生物學家研究一種藻類產生的毒素。","original_meaning":"毒素","original_example":"The concept is easy to explain.","original_example_zh":"這個概念很容易解釋。"},{"source_id":3945,"word":"trademark","meaning":"商標","example":"The company registered a trademark for its distinctive symbol.","example_zh":"公司為獨特標誌註冊商標。","original_meaning":"商標","original_example":"His condition improved after treatment.","original_example_zh":"治療後他的狀況有所好轉。"},{"source_id":3946,"word":"transaction","meaning":"交易","example":"The cashier recorded the transaction after the customer bought the book.","example_zh":"顧客買書後，收銀員記錄這筆交易。","original_meaning":"交易","original_example":"The connection remained stable throughout.","original_example_zh":"連線始終保持穩定。"},{"source_id":3947,"word":"transcript","meaning":"成績單","example":"She requested a transcript before applying to the university.","example_zh":"申請大學前，她申請了一份成績單。","original_meaning":"成績單","original_example":"The contract was renewed for another year.","original_example_zh":"合約續約一年。"},{"source_id":3948,"word":"transformation","meaning":"轉變","example":"The transformation of the empty lot into a garden amazed the neighbors.","example_zh":"空地變成花園的轉變讓鄰居驚喜。","original_meaning":"轉變","original_example":"The cost increased due to inflation.","original_example_zh":"成本因通貨膨脹而上升。"},{"source_id":3949,"word":"transgression","meaning":"違規","example":"The referee explained the transgression that had broken the game's rules.","example_zh":"裁判解釋那項違反比賽規則的行為。","original_meaning":"違規","original_example":"The customer was satisfied with the service.","original_example_zh":"客戶對服務感到滿意。"},{"source_id":3950,"word":"transition","meaning":"過渡","example":"The transition from school to university brought new responsibilities.","example_zh":"從高中到大學的過渡帶來新的責任。","original_meaning":"過渡","original_example":"The data was analyzed using AI tools.","original_example_zh":"資料是透過人工智慧工具進行分析的。"},{"source_id":3951,"word":"transparency","meaning":"透明","example":"The transparency of the glass allowed us to see the roots clearly.","example_zh":"玻璃的透明性讓我們清楚看到根部。","original_meaning":"透明","original_example":"The decision was made after careful review.","original_example_zh":"經過仔細審查後做出了決定。"},{"source_id":3952,"word":"transplant","meaning":"移植","example":"The gardener prepared the young tree for transplant to a larger space.","example_zh":"園丁準備把幼樹移植到較寬敞的地方。","original_meaning":"移植","original_example":"Demand for electric cars is rising.","original_example_zh":"電動車的需求正在上升。"},{"source_id":3953,"word":"trauma","meaning":"創傷","example":"The counselor supported the family as they recovered from the trauma of the disaster.","example_zh":"輔導員支持那個家庭，協助他們走過災難帶來的心理創傷。","original_meaning":"創傷","original_example":"The design combines style and function.","original_example_zh":"這款設計兼具風格與功能。"},{"source_id":3954,"word":"treason","meaning":"叛國","example":"The historical trial concerned an accusation of treason against the crown.","example_zh":"這場歷史審判涉及背叛王室的叛國指控。","original_meaning":"叛國","original_example":"The development process took several months.","original_example_zh":"開發過程耗時數月。"},{"source_id":3955,"word":"tribunal","meaning":"法庭","example":"The tribunal listened to both sides before reaching a decision.","example_zh":"法庭聽取雙方陳述後才作出決定。","original_meaning":"法庭","original_example":"The device works smoothly without issues.","original_example_zh":"這台設備運作順暢，毫無問題。"},{"source_id":3956,"word":"tribute","meaning":"致敬","example":"The concert was a tribute to the retired music teacher.","example_zh":"這場音樂會向退休音樂老師致敬。","original_meaning":"致敬","original_example":"The difference is easy to notice.","original_example_zh":"差異顯而易見。"},{"source_id":3957,"word":"trusteeship","meaning":"託管","example":"The historic house was placed under the trusteeship of a local foundation.","example_zh":"這棟歷史建築交由當地基金會託管。","original_meaning":"託管","original_example":"The director approved the final cut.","original_example_zh":"導演批准了最終剪輯版本。"},{"source_id":3958,"word":"tuberculosis","meaning":"結核病","example":"The public-health exhibit explained the history of tuberculosis.","example_zh":"公共衛生展覽介紹結核病的歷史。","original_meaning":"結核病","original_example":"The discussion led to new ideas.","original_example_zh":"討論激發了新想法。"},{"source_id":3959,"word":"turmoil","meaning":"動亂","example":"The sudden cancellation threw the festival preparations into turmoil.","example_zh":"突然取消活動，讓節慶籌備陷入混亂。","original_meaning":"動亂","original_example":"The document was reviewed by the legal team.","original_example_zh":"該文件已由法律團隊審閱。"},{"source_id":3960,"word":"tyranny","meaning":"暴政","example":"The novel portrayed villagers resisting the ruler's tyranny.","example_zh":"小說描繪村民反抗統治者的暴政。","original_meaning":"暴政","original_example":"The effect of the medicine was immediate.","original_example_zh":"藥效立竿見影。"},{"source_id":3961,"word":"ultimatum","meaning":"最後通牒","example":"The owner gave the contractor an ultimatum to finish the repairs or lose the contract.","example_zh":"業主發出最後通牒，要求承包商完成修繕，否則終止合約。","original_meaning":"最後通牒","original_example":"Her effort was recognized by the manager.","original_example_zh":"她的努力獲得了經理的認可。"},{"source_id":3962,"word":"unanimity","meaning":"一致","example":"The committee reached unanimity on keeping the library open longer.","example_zh":"委員會一致同意延長圖書館開放時間。","original_meaning":"一致","original_example":"The employee was promoted for his performance.","original_example_zh":"該員工因表現優異而獲得晉升。"},{"source_id":3963,"word":"underestimate","meaning":"低估","example":"We should not underestimate how much wood the large model will need.","example_zh":"我們不應低估大型模型所需的木材量。","original_meaning":"低估","original_example":"Energy consumption has increased recently.","original_example_zh":"近期能源消耗有所增加。"},{"source_id":3964,"word":"unemployment","meaning":"失業","example":"The factory closure led to unemployment in the town.","example_zh":"工廠關閉導致城鎮失業增加。","original_meaning":"失業","original_example":"The environment must be protected for future generations.","original_example_zh":"為了子孫後代，必須保護環境。"},{"source_id":3965,"word":"unification","meaning":"統一","example":"The exhibit traced the unification of several small kingdoms.","example_zh":"展覽追溯數個小王國的統一過程。","original_meaning":"統一","original_example":"The equipment was upgraded to the latest model.","original_example_zh":"設備已升級至最新型號。"},{"source_id":3966,"word":"uprising","meaning":"起義","example":"The painting depicted an uprising against unfair taxes.","example_zh":"畫作描繪反抗不公平稅制的起義。","original_meaning":"起義","original_example":"The error was fixed in the latest patch.","original_example_zh":"錯誤已在最新修補程式中修正。"},{"source_id":3967,"word":"utilization","meaning":"利用","example":"Better utilization of the courtyard created more space for reading.","example_zh":"更有效利用庭院，創造了更多閱讀空間。","original_meaning":"利用","original_example":"The event attracted thousands of visitors.","original_example_zh":"該活動吸引了數千名訪客。"},{"source_id":3968,"word":"vaccination","meaning":"疫苗接種","example":"The nurse prepared the vaccination room before the clinic opened.","example_zh":"診所開門前，護理師準備好疫苗接種室。","original_meaning":"疫苗接種","original_example":"Vaccination helps protect people from serious diseases.","original_example_zh":"接種疫苗有助於保護人們免於罹患嚴重疾病。"},{"source_id":3969,"word":"validity","meaning":"有效性","example":"The researcher checked the validity of the results by repeating the experiment.","example_zh":"研究者重複實驗，檢查結果的有效性。","original_meaning":"有效性","original_example":"The experiment confirmed the hypothesis.","original_example_zh":"實驗證實了該假說。"},{"source_id":3970,"word":"vegetation","meaning":"植被","example":"Thick vegetation covered the hillside after the rainy season.","example_zh":"雨季過後，濃密植被覆蓋山坡。","original_meaning":"植被","original_example":"The experience changed his perspective.","original_example_zh":"這段經歷改變了他的觀點。"},{"source_id":3971,"word":"ventilation","meaning":"通風","example":"The high windows improved ventilation in the classroom.","example_zh":"高處窗戶改善教室通風。","original_meaning":"通風","original_example":"A new feature was added to the app.","original_example_zh":"應用程式新增了一項功能。"},{"source_id":3972,"word":"verification","meaning":"驗證","example":"The archivist completed the verification of the photograph's date.","example_zh":"檔案員完成照片日期的驗證。","original_meaning":"驗證","original_example":"User feedback helps improve the product.","original_example_zh":"用戶回饋有助於改善產品。"},{"source_id":3973,"word":"versatility","meaning":"多才多藝","example":"The musician's versatility allowed her to play several instruments.","example_zh":"那位音樂家多才多藝，能演奏數種樂器。","original_meaning":"多才多藝","original_example":"The file was saved successfully.","original_example_zh":"檔案已成功儲存。"},{"source_id":3974,"word":"veto","meaning":"否決","example":"The president used a veto to block the proposed law.","example_zh":"總統行使否決權，阻止法案通過。","original_meaning":"否決","original_example":"The function returns a boolean value.","original_example_zh":"該函式會傳回一個布林值。"},{"source_id":3975,"word":"vigilance","meaning":"警覺","example":"The lifeguard's vigilance helped keep swimmers safe.","example_zh":"救生員的警覺有助維護游泳者安全。","original_meaning":"警覺","original_example":"The team achieved its goal ahead of schedule.","original_example_zh":"團隊提前達成了目標。"},{"source_id":3976,"word":"vindication","meaning":"平反","example":"The new evidence brought vindication for the wrongly accused worker.","example_zh":"新證據讓遭錯誤指控的員工獲得平反。","original_meaning":"平反","original_example":"The company experienced steady growth.","original_example_zh":"該公司經歷了穩定的成長。"},{"source_id":3977,"word":"violation","meaning":"違反","example":"Parking in front of the emergency exit was a violation of the rules.","example_zh":"在緊急出口前停車違反規定。","original_meaning":"違反","original_example":"It was an innovative idea.","original_example_zh":"這是一個創新的想法。"},{"source_id":3978,"word":"virtue","meaning":"美德","example":"Her patience was a virtue that helped the whole team learn.","example_zh":"她的耐心是幫助全隊學習的美德。","original_meaning":"美德","original_example":"The image quality is very clear.","original_example_zh":"畫質非常清晰。"},{"source_id":3979,"word":"visualization","meaning":"視覺化","example":"The visualization made the river's flow easier to understand.","example_zh":"視覺化呈現讓河水流向更容易理解。","original_meaning":"視覺化","original_example":"The impact of the policy was significant.","original_example_zh":"該政策的影響顯著。"},{"source_id":3980,"word":"vocation","meaning":"職業；志業","example":"Teaching became her vocation after years of helping younger students.","example_zh":"多年協助年幼學生後，教學成了她的志業。","original_meaning":"職業","original_example":"There was a noticeable improvement in performance.","original_example_zh":"表現有明顯的進步。"},{"source_id":3981,"word":"volatility","meaning":"波動性","example":"The lesson used a changing graph to illustrate market volatility.","example_zh":"課程用變動圖表說明市場波動性。","original_meaning":"波動性","original_example":"The increase in sales was expected.","original_example_zh":"銷售額的增長在預期之中。"},{"source_id":3982,"word":"vulnerability","meaning":"脆弱性","example":"The storm revealed the vulnerability of the old roof.","example_zh":"風暴顯露老屋頂的脆弱性。","original_meaning":"脆弱性","original_example":"The information provided was accurate.","original_example_zh":"所提供的資訊是準確的。"},{"source_id":3983,"word":"warehouse","meaning":"倉庫","example":"The warehouse stored books before they were sent to schools.","example_zh":"倉庫存放準備送往學校的書籍。","original_meaning":"倉庫","original_example":"User input is required before submission.","original_example_zh":"提交前需輸入使用者資料。"},{"source_id":3984,"word":"watershed","meaning":"集水區；分水嶺","example":"The model showed how streams within a watershed drain toward the same river.","example_zh":"模型展示集水區內的溪流如何匯向同一條河。","original_meaning":"集水區；分水嶺","original_example":"Volunteers planted trees upstream to protect the town's watershed.","original_example_zh":"志工在上游種樹，保護城鎮的集水區。"},{"source_id":3985,"word":"wavelength","meaning":"波長","example":"The distance between two neighboring wave crests is one wavelength.","example_zh":"兩個相鄰波峰之間的距離是一個波長。","original_meaning":"波長","original_example":"The item was delivered on time.","original_example_zh":"商品準時送達。"},{"source_id":3986,"word":"wedge","meaning":"楔子","example":"The carpenter used a wooden wedge to hold the door open.","example_zh":"木匠用木楔讓門保持開啟。","original_meaning":"楔子","original_example":"The job was completed successfully.","original_example_zh":"工作已成功完成。"},{"source_id":3987,"word":"whistle","meaning":"口哨；哨子","example":"The coach raised a whistle to signal the start of practice.","example_zh":"教練舉起哨子，示意練習開始。","original_meaning":"口哨","original_example":"The key to success is consistency.","original_example_zh":"成功的關鍵在於持之以恆。"},{"source_id":3988,"word":"wholesale","meaning":"批發的","example":"The shop bought notebooks at wholesale prices.","example_zh":"商店以批發價格購買筆記本。","original_meaning":"批發的","original_example":"This knowledge is useful in real life.","original_example_zh":"這項知識在現實生活中很有用。"},{"source_id":3989,"word":"wilderness","meaning":"荒野","example":"The hikers admired the wilderness from a marked trail.","example_zh":"健行者從有標示的步道欣賞荒野。","original_meaning":"荒野","original_example":"They hiked deep into the wilderness.","original_example_zh":"他們深入荒野徒步旅行。"},{"source_id":3990,"word":"windfall","meaning":"意外之財","example":"The unexpected donation was a windfall for the school library.","example_zh":"意外捐款成了學校圖書館的一筆意外之財。","original_meaning":"意外之財","original_example":"Winning the lottery was an unexpected windfall.","original_example_zh":"中獎是一筆意想不到的意外之財。"},{"source_id":3991,"word":"workforce","meaning":"勞動力","example":"The company's workforce included skilled technicians and designers.","example_zh":"公司的員工包括技術熟練的技師與設計師。","original_meaning":"勞動力","original_example":"The company plans to expand its workforce.","original_example_zh":"該公司計劃擴充人力。"},{"source_id":3992,"word":"workshop","meaning":"工作坊","example":"The students joined a workshop on repairing bicycles.","example_zh":"學生參加修理自行車的工作坊。","original_meaning":"工作坊","original_example":"She attended a writing workshop last weekend.","original_example_zh":"她上週末參加了一個寫作工作坊。"},{"source_id":3993,"word":"xenophobia","meaning":"仇外","example":"The play challenged xenophobia by showing friendships across cultures.","example_zh":"戲劇透過跨文化友誼，挑戰仇外心理。","original_meaning":"仇外","original_example":"Education can help reduce xenophobia.","original_example_zh":"教育有助於減輕排外情緒。"},{"source_id":3994,"word":"yearning","meaning":"渴望","example":"Her yearning to see the ocean inspired many paintings.","example_zh":"她渴望看見海洋，因此創作許多畫作。","original_meaning":"渴望","original_example":"He felt a deep yearning for home.","original_example_zh":"他對家鄉懷有深深的思念。"},{"source_id":3995,"word":"zenith","meaning":"頂點；天頂","example":"The sun approached its zenith above the quiet courtyard.","example_zh":"太陽逐漸接近寧靜庭院上空的天頂。","original_meaning":"頂點","original_example":"The singer reached the zenith of her career.","original_example_zh":"這位歌手達到了事業的巔峰。"},{"source_id":3996,"word":"zoology","meaning":"動物學","example":"The zoology lesson compared the structures of different bird wings.","example_zh":"動物學課比較不同鳥類翅膀的構造。","original_meaning":"動物學","original_example":"Zoology is the study of animals.","original_example_zh":"動物學是研究動物的學科。"},{"source_id":3997,"word":"abbreviation","meaning":"縮寫","example":"The teacher explained an abbreviation in the science article.","example_zh":"老師解釋科學文章中的一個縮寫。","original_meaning":"縮寫","original_example":"Use the abbreviation.","original_example_zh":"使用縮寫。"},{"source_id":3998,"word":"abdomen","meaning":"腹部","example":"The model showed the organs located in the abdomen.","example_zh":"模型展示位於腹部的器官。","original_meaning":"腹部","original_example":"Pain in the abdomen.","original_example_zh":"腹痛。"},{"source_id":3999,"word":"abolition","meaning":"廢除","example":"The exhibit explored the movement for the abolition of slavery.","example_zh":"展覽探討廢除奴隸制度的運動。","original_meaning":"廢除","original_example":"The abolition of slavery.","original_example_zh":"廢除奴隸制。"},{"source_id":4000,"word":"abortion","meaning":"墮胎","example":"The public-health lecture discussed abortion with care and respect.","example_zh":"公共衛生講座謹慎而尊重地討論墮胎議題。","original_meaning":"墮胎","original_example":"A controversial topic.","original_example_zh":"一個具爭議性的話題。"},{"source_id":4001,"word":"abound","meaning":"充斥；大量存在","example":"Wildflowers abound in the meadow during spring.","example_zh":"春天的草地上開滿野花。","original_meaning":"充斥","original_example":"Fish abound in the lake.","original_example_zh":"湖中魚群繁多。"},{"source_id":4002,"word":"absentee","meaning":"缺席者","example":"The teacher left a copy of the notes for the absentee.","example_zh":"老師為缺席者留下一份筆記。","original_meaning":"缺席者","original_example":"An absentee ballot.","original_example_zh":"缺席選票。"},{"source_id":4003,"word":"absorption","meaning":"吸收","example":"The sponge's absorption of water made it noticeably heavier.","example_zh":"海綿吸水後明顯變重。","original_meaning":"吸收","original_example":"Light absorption.","original_example_zh":"光吸收。"},{"source_id":4004,"word":"abstinence","meaning":"戒絕","example":"He practiced abstinence from alcohol while focusing on his health.","example_zh":"他專注健康，選擇戒酒。","original_meaning":"戒絕","original_example":"Practice abstinence.","original_example_zh":"實踐禁慾。"},{"source_id":4005,"word":"acceleration","meaning":"加速","example":"The students measured the toy car's acceleration as it rolled down the ramp.","example_zh":"學生測量玩具車沿斜坡滾下時的加速度。","original_meaning":"加速","original_example":"The rate of acceleration.","original_example_zh":"加速度。"},{"source_id":4006,"word":"accomplice","meaning":"共犯","example":"The detective questioned the suspect's accomplice about the stolen painting.","example_zh":"偵探就失竊畫作詢問嫌疑人的共犯。","original_meaning":"共犯","original_example":"An accomplice in crime.","original_example_zh":"犯罪的同夥。"},{"source_id":4007,"word":"accumulation","meaning":"積累","example":"The accumulation of fallen leaves blocked the small drain.","example_zh":"落葉堆積，堵住了小排水口。","original_meaning":"積累","original_example":"Wealth accumulation.","original_example_zh":"財富累積。"},{"source_id":4008,"word":"acquaintance","meaning":"認識的人；熟人","example":"I met an old acquaintance at the community book fair.","example_zh":"我在社區書展遇到一位老熟人。","original_meaning":"認識的人；熟人","original_example":"An acquaintance from cram school recognized me at the book fair.","original_example_zh":"一位補習班認識的人在書展認出了我。"},{"source_id":4009,"word":"activism","meaning":"行動主義","example":"Her environmental activism encouraged the school to reduce plastic waste.","example_zh":"她的環保行動鼓勵學校減少塑膠垃圾。","original_meaning":"行動主義","original_example":"Political activism.","original_example_zh":"政治行動主義。"},{"source_id":4010,"word":"acupuncture","meaning":"針灸","example":"The museum explained the history of acupuncture.","example_zh":"博物館介紹針灸的歷史。","original_meaning":"針灸","original_example":"Try acupuncture.","original_example_zh":"試試針灸。"},{"source_id":4011,"word":"adamant","meaning":"堅定的","example":"She was adamant that every team member should have a turn.","example_zh":"她堅持每位隊員都應輪到一次。","original_meaning":"堅定的","original_example":"She was adamant.","original_example_zh":"她態度堅決。"},{"source_id":4012,"word":"adaptation","meaning":"改編","example":"The school play was an adaptation of a classic adventure novel.","example_zh":"學校戲劇改編自經典冒險小說。","original_meaning":"改編","original_example":"A film adaptation.","original_example_zh":"電影改編版。"},{"source_id":4013,"word":"additive","meaning":"添加劑","example":"The scientist tested an additive that changed the paint's texture.","example_zh":"科學家測試一種改變顏料質地的添加劑。","original_meaning":"添加劑","original_example":"Food additives.","original_example_zh":"食品添加物。"},{"source_id":4014,"word":"adequacy","meaning":"充足","example":"The guide checked the adequacy of the team's water supplies.","example_zh":"嚮導檢查隊伍的飲水是否充足。","original_meaning":"充足","original_example":"Test the adequacy.","original_example_zh":"測試是否足夠。"},{"source_id":4015,"word":"adherence","meaning":"堅持","example":"Her adherence to the plan kept the project on schedule.","example_zh":"她堅持遵守計畫，讓專案如期進行。","original_meaning":"堅持","original_example":"Adherence to rules.","original_example_zh":"遵守規則。"},{"source_id":4016,"word":"adjective","meaning":"形容詞","example":"The teacher used an adjective to describe the colorful bird.","example_zh":"老師用形容詞描述那隻色彩鮮豔的鳥。","original_meaning":"形容詞","original_example":"Use an adjective.","original_example_zh":"使用形容詞。"},{"source_id":4017,"word":"administrator","meaning":"管理員","example":"The administrator organized the school's registration records.","example_zh":"管理員整理學校註冊資料。","original_meaning":"管理員","original_example":"A system administrator.","original_example_zh":"系統管理員。"},{"source_id":4018,"word":"admiration","meaning":"讚賞","example":"The audience watched the young musician with admiration.","example_zh":"觀眾以讚賞眼光欣賞年輕音樂家的演奏。","original_meaning":"讚賞","original_example":"Full of admiration.","original_example_zh":"充滿敬佩。"},{"source_id":4019,"word":"adoption","meaning":"採用","example":"The adoption of reusable containers reduced waste at the festival.","example_zh":"採用可重複使用容器，減少節慶垃圾。","original_meaning":"採用","original_example":"Technology adoption.","original_example_zh":"技術採用。"},{"source_id":4020,"word":"adornment","meaning":"裝飾","example":"A simple ribbon was the only adornment on the gift box.","example_zh":"簡單絲帶是禮物盒上唯一裝飾。","original_meaning":"裝飾","original_example":"Body adornment.","original_example_zh":"身體裝飾。"},{"source_id":4021,"word":"adversity","meaning":"逆境","example":"The team learned to cooperate in the face of adversity.","example_zh":"團隊在逆境中學會合作。","original_meaning":"逆境","original_example":"Overcome adversity.","original_example_zh":"克服逆境。"},{"source_id":4022,"word":"advocacy","meaning":"倡導","example":"Her advocacy for accessible paths helped improve the park.","example_zh":"她倡導無障礙步道，協助改善公園。","original_meaning":"倡導","original_example":"Patient advocacy.","original_example_zh":"患者權益倡導。"},{"source_id":4023,"word":"aerospace","meaning":"航太","example":"The aerospace exhibition displayed models of aircraft and spacecraft.","example_zh":"航太展覽展示飛機與太空船模型。","original_meaning":"航太","original_example":"The aerospace industry.","original_example_zh":"航空航天產業。"},{"source_id":4024,"word":"affidavit","meaning":"宣誓書","example":"The witness signed an affidavit describing what she had seen.","example_zh":"證人簽署宣誓書，說明她所見的情況。","original_meaning":"宣誓書","original_example":"Sign an affidavit.","original_example_zh":"簽署宣誓書。"},{"source_id":4025,"word":"affiliation","meaning":"隸屬","example":"Her affiliation with the museum gave her access to its research library.","example_zh":"她與博物館的隸屬關係讓她能使用研究圖書館。","original_meaning":"隸屬","original_example":"Political affiliation.","original_example_zh":"政治立場。"},{"source_id":4026,"word":"affirmation","meaning":"肯定","example":"The teacher's affirmation gave the nervous speaker confidence.","example_zh":"老師的肯定讓緊張的講者增添信心。","original_meaning":"肯定","original_example":"A positive affirmation.","original_example_zh":"正向肯定。"},{"source_id":4027,"word":"aftermath","meaning":"後果","example":"Volunteers repaired the garden in the aftermath of the storm.","example_zh":"風暴過後，志工修復花園。","original_meaning":"後果","original_example":"The aftermath of war.","original_example_zh":"戰爭的後果。"},{"source_id":4028,"word":"aggravation","meaning":"加劇","example":"The blocked drain led to the aggravation of the flooding.","example_zh":"排水口堵塞，使淹水更加嚴重。","original_meaning":"加劇","original_example":"Avoid aggravation.","original_example_zh":"避免激化矛盾。"},{"source_id":4029,"word":"agitation","meaning":"煽動；不安騷動","example":"The speech caused agitation among people worried about the factory closure.","example_zh":"演說使擔心工廠關閉的人們更加不安。","original_meaning":"煽動","original_example":"Political agitation.","original_example_zh":"政治煽動。"},{"source_id":4030,"word":"agnostic","meaning":"不可知論者","example":"The agnostic said she was uncertain whether a deity exists.","example_zh":"那位不可知論者說，她不確定神祇是否存在。","original_meaning":"不可知論者","original_example":"An agnostic view.","original_example_zh":"不可知論的觀點。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-taxonomy-01-v1","level":"senior","word":"taxonomy","sort_order":1,"sense":"分類學","alt_zh":"老師與高中生在自然館用哺乳類、鳥類、昆蟲模型分類，無文字。","example":"The taxonomy lesson grouped animals by their shared characteristics.","example_zh":"分類學課程依共同特徵將動物分組。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/taxonomy-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-technocrat-01-v1","level":"senior","word":"technocrat","sort_order":1,"sense":"技術官僚","alt_zh":"成年技術專家在市政會議向代表解說供水管路模型。","example":"The technocrat advised the council on improving the city's water system.","example_zh":"技術官僚就改善城市供水系統向議會提出建議。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/technocrat-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-telecommunications-01-v1","level":"senior","word":"telecommunications","sort_order":1,"sense":"電信","alt_zh":"高中生在科技博物館參觀電纜、舊電話與通訊衛星模型。","example":"The exhibition traced the development of telecommunications from cables to satellites.","example_zh":"展覽回顧電信從電纜到衛星的發展。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/telecommunications-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-temperament-01-v1","level":"senior","word":"temperament","sort_order":1,"sense":"性情","alt_zh":"成年照護員在安全馬廄輕撫平靜的馬，高中訪客在欄外微笑觀看。","example":"The horse's gentle temperament made it easy to handle.","example_zh":"那匹馬溫和的性情讓人容易照料。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/temperament-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-tenant-01-v1","level":"senior","word":"tenant","sort_order":1,"sense":"房客","alt_zh":"成年房客在公寓向成年房東指出窗框滲水處，雙方平靜討論。","example":"The tenant asked the landlord to repair the leaking window.","example_zh":"房客請房東修理漏水的窗戶。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/tenant-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-territorial-01-v1","level":"senior","word":"territorial","sort_order":1,"sense":"領土的","alt_zh":"歷史老師向高中生展示虛構古王國立體地圖，以清楚色塊邊界標示疆域，無文字。","example":"The map showed the territorial boundaries of the ancient kingdom.","example_zh":"地圖顯示古代王國的領土邊界。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/territorial-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-testament-01-v1","level":"senior","word":"testament","sort_order":1,"sense":"證明；明證","alt_zh":"成年志工與高中生欣賞修復後花木茂盛的社區花園，手邊收好園藝工具。","example":"The flourishing garden was a testament to the volunteers' hard work.","example_zh":"茂盛花園是志工辛勤付出的明證。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/testament-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-testimony-01-v1","level":"senior","word":"testimony","sort_order":1,"sense":"證詞","alt_zh":"成年女性證人在法庭平靜向法官陳述，律師專心聆聽，無犯罪畫面。","example":"The witness gave testimony about what she had seen.","example_zh":"證人就她所見的情況作證。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/testimony-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-theology-01-v1","level":"senior","word":"theology","sort_order":1,"sense":"神學","alt_zh":"成年學者在古老宗教研究圖書館與高中訪客討論書籍，態度尊重莊重。","example":"The library held a collection of books on theology.","example_zh":"圖書館收藏一系列神學書籍。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/theology-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-therapeutic-01-v1","level":"senior","word":"therapeutic","sort_order":1,"sense":"治療的","alt_zh":"成年治療師在安靜專業診所與成年個案進行溫和活動，無療效宣稱或操作指示。","example":"The clinic offered a therapeutic program supervised by trained professionals.","example_zh":"診所提供由受訓專業人員監督的治療課程。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/therapeutic-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-thesis-01-v1","level":"senior","word":"thesis","sort_order":1,"sense":"論文","alt_zh":"成年大學生在學術教室向評審展示歷史橋梁模型與論文，無可讀文字。","example":"She presented her thesis on the history of the town's bridges.","example_zh":"她發表研究城鎮橋梁歷史的論文。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/thesis-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-thoroughfare-01-v1","level":"senior","word":"thoroughfare","sort_order":1,"sense":"幹道","alt_zh":"俯看城鎮寬敞主要道路從車站延伸到市中心，行人與車輛有序通行。","example":"The main thoroughfare connected the station with the town center.","example_zh":"主要幹道連接車站與市中心。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/thoroughfare-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-totalitarian-01-v1","level":"senior","word":"totalitarian","sort_order":1,"sense":"極權的","alt_zh":"高中生在博物館觀看虛構極權政府集中控制報紙、廣播與集會的模型，無標語傷害。","example":"The history exhibit examined life under a totalitarian regime.","example_zh":"歷史展覽探討極權政體下的生活。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/totalitarian-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-toxin-01-v1","level":"senior","word":"toxin","sor